// ══════════════════════════════════════════════════════════════════════
// td/story/lines/firstpair.js — day one: the two who clicked, and the two who didn't
// ══════════════════════════════════════════════════════════════════════
// Spec docs/superpowers/specs/2026-10-10-td-first-impressions-design.md (§3 is the register, its five
// reference scenes are the bar). Rewritten 2026-10-10 after the user's review of the first build: "the
// writing isn't at the level we agreed" — flat, about bags, "I'd like" and written lines, no turn, few jokes.
// Every scene here: somebody doing something specific, an attitude on each side, one moment where it turns,
// a joke that lands on first read, and a confessional each saying how they feel about the other one.
// Columns of say(): neutral, then the five voice families: sharp (cruel/schemer/proud/bossy), dry
// (dry/calm/quiet/nerdy), loud (loud/blunt/tough/competitive/chaotic), soft (warm/earnest/emotional/anxious/
// flirty), odd (goofy/ditzy/food/theatrical). Every variant answers the same line before it.
// Day one: nobody shares a past ("again", "always", "used to" never), no outdoor nouns the jet doesn't
// have, no venue nouns ({bed}, {here}), no dinner in the morning scenes (clicked) or breakfast in the evening
// ones (clashed). The kit scenes are built in kits.js (kitFirstPairScene) from the character's own kit.
const say = (by, neutral, sharp, dry, loud, soft, odd) => ({ by, say: neutral, v: { sharp, dry, loud, soft, odd } });
const conf = (by, ...lines) => { const t = say(by, ...lines); return { by, conf: t.say, v: t.v }; };
const beat = text => ({ beat: text });

